            return Promise.resolve(false);
        if ("error" in captured)
            return Promise.reject(captured.error);
        const { run, snapshot: expectedStatusSnapshot } = captured;
        if (!hasExpectedRunStatus(expectedStatusSnapshot, run.status) || run.workerId !== expectedWorkerId) {
            return Promise.resolve(false);
        }
